SELECT trading_date,item_name,quantity_sold,amount,total_tax,sale_closed_ten_minute_time,adjustment FROM resolved_sale_line WHERE trading_date BETWEEN '2026-10-30' AND '2026-11-01' AND item_name IN ('House Vodka - 30ml','Pint - Carlton Draught') AND sale_closed_ten_minute_time < '05:00' ORDER BY trading_date,sale_closed_ten_minute_time LIMIT 20;
SELECT trading_date,sum(amount) gross,sum((adjustment->>'finalExTax')::numeric) net,count(*) lines FROM resolved_sale_line WHERE trading_date BETWEEN '2026-10-26' AND '2026-11-01' AND sale_closed_ten_minute_time < '05:00' GROUP BY 1 ORDER BY 1;
SELECT r.fetcher_identity,r.source_record_ref,r.fetched_at,left(convert_from(r.payload_bytes,'UTF8'),170) prefix FROM raw_record r JOIN canonical_daily_sales s ON s.raw_record_id=r.id WHERE s.superseded_at IS NULL AND s.source_system='LIGHTSPEED' AND s.trading_date BETWEEN '2026-10-26' AND '2026-11-01' ORDER BY s.trading_date;
